INSERT INTO ef_bncc_payload VALUES($bncc${"subjects":[{"key":"ef-comp-ar","name":"Arte","metadata":{"datasetCommit":"daabd7dd63ae0cac0aa520b6189e79f95c24f583","competencies":[{"id":"ef-area-linguagens-ce-01","documento":"bncc-2018","tipo":"especifica_de_area","area":"ef-area-linguagens","numero":1,"texto":"Compreender as linguagens como construção humana, histórica, social e cultural, de natureza dinâmica, reconhecendo-as e valorizando-as como formas de significação da realidade e expressão de subjetividades e identidades sociais e culturais.","fonte":{"documento":"bncc-2018","arquivo":"BNCC_Ensino Fundamental.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comps. de Linguagens"}},{"id":"ef-area-linguagens-ce-02","documento":"bncc-2018","tipo":"especifica_de_area","area":"ef-area-linguagens","numero":2,"texto":"Conhecer e explorar diversas práticas de linguagem (artísticas, corporais e linguísticas) em diferentes campos da atividade humana para continuar aprendendo, ampliar suas possibilidades de participação na vida social e colaborar para a construção de uma sociedade mais justa, democrática e inclusiva.","fonte":{"documento":"bncc-2018","arquivo":"BNCC_Ensino Fundamental.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comps. de Linguagens"}},{"id":"ef-area-linguagens-ce-03","documento":"bncc-2018","tipo":"especifica_de_area","area":"ef-area-linguagens","numero":3,"texto":"Utilizar diferentes linguagens – verbal (oral ou visual-motora, como Libras, e escrita), corporal, visual, sonora e digital –, para se expressar e partilhar informações, experiências, ideias e sentimentos em diferentes contextos e produzir sentidos que levem ao diálogo, à resolução de conflitos e à cooperação.","fonte":{"documento":"bncc-2018","arquivo":"BNCC_Ensino Fundamental.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comps. de Linguagens"}},{"id":"ef-area-linguagens-ce-04","documento":"bncc-2018","tipo":"especifica_de_area","area":"ef-area-linguagens","numero":4,"texto":"Utilizar diferentes linguagens para defender pontos de vista que respeitem o outro e promovam os direitos humanos, a consciência socioambiental e o consumo responsável em âmbito local, regional e global, atuando criticamente frente a questões do mundo contemporâneo.","fonte":{"documento":"bncc-2018","arquivo":"BNCC_Ensino Fundamental.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comps. de Linguagens"}},{"id":"ef-area-linguagens-ce-05","documento":"bncc-2018","tipo":"especifica_de_area","area":"ef-area-linguagens","numero":5,"texto":"Desenvolver o senso estético para reconhecer, fruir e respeitar as diversas manifestações artísticas e culturais, das locais às mundiais, inclusive aquelas pertencentes ao patrimônio cultural da humanidade, bem como participar de práticas diversificadas, individuais e coletivas, da produção artístico-cultural, com respeito à diversidade de saberes, identidades e culturas.","fonte":{"documento":"bncc-2018","arquivo":"BNCC_Ensino Fundamental.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comps. de Linguagens"}},{"id":"ef-area-linguagens-ce-06","documento":"bncc-2018","tipo":"especifica_de_area","area":"ef-area-linguagens","numero":6,"texto":"Compreender e utilizar tecnologias digitais de informação e comunicação de forma crítica, significativa, reflexiva e ética nas diversas práticas sociais (incluindo as escolares), para se comunicar por meio das diferentes linguagens e mídias, produzir conhecimentos, resolver problemas e desenvolver projetos autorais e coletivos.","fonte":{"documento":"bncc-2018","arquivo":"BNCC_Ensino Fundamental.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comps. de Linguagens"}},{"id":"ef-comp-ar-ce-01","documento":"bncc-2018","tipo":"especifica_de_componente","componente":"ef-comp-ar","numero":1,"texto":"Explorar, conhecer, fruir e analisar criticamente práticas e produções artísticas e culturais do seu entorno social, dos povos indígenas, das comunidades tradicionais brasileiras e de diversas sociedades, em distintos tempos e espaços, para reconhecer a arte como um fenômeno cultural, histórico, social e sensível a diferentes contextos e dialogar com as diversidades.","fonte":{"documento":"bncc-2018","arquivo":"BNCC_Ensino Fundamental.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comps. de Arte"}},{"id":"ef-comp-ar-ce-02","documento":"bncc-2018","tipo":"especifica_de_componente","componente":"ef-comp-ar","numero":2,"texto":"Compreender as relações entre as linguagens da Arte e suas práticas integradas, inclusive aquelas possibilitadas pelo uso das novas tecnologias de informação e comunicação, pelo cinema e pelo audiovisual, nas condições particulares de produção, na prática de cada linguagem e nas suas articulações.","fonte":{"documento":"bncc-2018","arquivo":"BNCC_Ensino Fundamental.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comps. de Arte"}},{"id":"ef-comp-ar-ce-03","documento":"bncc-2018","tipo":"especifica_de_componente","componente":"ef-comp-ar","numero":3,"texto":"Pesquisar e conhecer distintas matrizes estéticas e culturais – especialmente aquelas manifestas na arte e nas culturas que constituem a identidade brasileira –, sua tradição e manifestações contemporâneas, reelaborando-as nas criações em Arte.","fonte":{"documento":"bncc-2018","arquivo":"BNCC_Ensino Fundamental.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comps. de Arte"}},{"id":"ef-comp-ar-ce-04","documento":"bncc-2018","tipo":"especifica_de_componente","componente":"ef-comp-ar","numero":4,"texto":"Experienciar a ludicidade, a percepção, a expressividade e a imaginação, ressignificando espaços da escola e de fora dela no âmbito da Arte.","fonte":{"documento":"bncc-2018","arquivo":"BNCC_Ensino Fundamental.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comps. de Arte"}},{"id":"ef-comp-ar-ce-05","documento":"bncc-2018","tipo":"especifica_de_componente","componente":"ef-comp-ar","numero":5,"texto":"Mobilizar recursos tecnológicos como formas de registro, pesquisa e criação artística.","fonte":{"documento":"bncc-2018","arquivo":"BNCC_Ensino Fundamental.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comps. de Arte"}},{"id":"ef-comp-ar-ce-06","documento":"bncc-2018","tipo":"especifica_de_componente","componente":"ef-comp-ar","numero":6,"texto":"Estabelecer relações entre arte, mídia, mercado e consumo, compreendendo, de forma crítica e problematizadora, modos de produção e de circulação da arte na sociedade.","fonte":{"documento":"bncc-2018","arquivo":"BNCC_Ensino Fundamental.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comps. de Arte"}},{"id":"ef-comp-ar-ce-07","documento":"bncc-2018","tipo":"especifica_de_componente","componente":"ef-comp-ar","numero":7,"texto":"Problematizar questões políticas, sociais, econômicas, científicas, tecnológicas e culturais, por meio de exercícios, produções, intervenções e apresentações artísticas.","fonte":{"documento":"bncc-2018","arquivo":"BNCC_Ensino Fundamental.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comps. de Arte"}},{"id":"ef-comp-ar-ce-08","documento":"bncc-2018","tipo":"especifica_de_componente","componente":"ef-comp-ar","numero":8,"texto":"Desenvolver a autonomia, a crítica, a autoria e o trabalho coletivo e colaborativo nas artes.","fonte":{"documento":"bncc-2018","arquivo":"BNCC_Ensino Fundamental.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comps. de Arte"}},{"id":"ef-comp-ar-ce-09","documento":"bncc-2018","tipo":"especifica_de_componente","componente":"ef-comp-ar","numero":9,"texto":"Analisar e valorizar o patrimônio artístico nacional e internacional, material e imaterial, com suas histórias e diferentes visões de mundo.","fonte":{"documento":"bncc-2018","arquivo":"BNCC_Ensino Fundamental.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comps. de Arte"}}]}},{"key":"ef-comp-ci","name":"Ciências","metadata":{"datasetCommit":"daabd7dd63ae0cac0aa520b6189e79f95c24f583","competencies":[{"id":"ef-area-ciencias-da-natureza-ce-01","documento":"bncc-2018","tipo":"especifica_de_area","area":"ef-area-ciencias-da-natureza","numero":1,"texto":"Compreender as Ciências da Natureza como empreendimento humano, e o conhecimento científico como provisório, cultural e histórico.","fonte":{"documento":"bncc-2018","arquivo":"BNCC_Ensino Fundamental.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comps. de Ciências da nature"}},{"id":"ef-area-ciencias-da-natureza-ce-02","documento":"bncc-2018","tipo":"especifica_de_area","area":"ef-area-ciencias-da-natureza","numero":2,"texto":"Compreender conceitos fundamentais e estruturas explicativas das Ciências da Natureza, bem como dominar processos, práticas e procedimentos da investigação científica, de modo a sentir segurança no debate de questões científicas, tecnológicas, socioambientais e do mundo do trabalho, continuar aprendendo e colaborar para a construção de uma sociedade justa, democrática e inclusiva.","fonte":{"documento":"bncc-2018","arquivo":"BNCC_Ensino Fundamental.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comps. de Ciências da nature"}},{"id":"ef-area-ciencias-da-natureza-ce-03","documento":"bncc-2018","tipo":"especifica_de_area","area":"ef-area-ciencias-da-natureza","numero":3,"texto":"Analisar, compreender e explicar características, fenômenos e processos relativos ao mundo natural, social e tecnológico (incluindo o digital), como também as relações que se estabelecem entre eles, exercitando a curiosidade para fazer perguntas, buscar respostas e criar soluções (inclusive tecnológicas) com base nos conhecimentos das Ciências da Natureza.","fonte":{"documento":"bncc-2018","arquivo":"BNCC_Ensino Fundamental.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comps. de Ciências da nature"}},{"id":"ef-area-ciencias-da-natureza-ce-04","documento":"bncc-2018","tipo":"especifica_de_area","area":"ef-area-ciencias-da-natureza","numero":4,"texto":"Avaliar aplicações e implicações políticas, socioambientais e culturais da ciência e de suas tecnologias para propor alternativas aos desafios do mundo contemporâneo, incluindo aqueles relativos ao mundo do trabalho.","fonte":{"documento":"bncc-2018","arquivo":"BNCC_Ensino Fundamental.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comps. de Ciências da nature"}},{"id":"ef-area-ciencias-da-natureza-ce-05","documento":"bncc-2018","tipo":"especifica_de_area","area":"ef-area-ciencias-da-natureza","numero":5,"texto":"Construir argumentos com base em dados, evidências e informações confiáveis e negociar e defender ideias e pontos de vista que promovam a consciência socioambiental e o respeito a si próprio e ao outro, acolhendo e valorizando a diversidade de indivíduos e de grupos sociais, sem preconceitos de qualquer natureza.","fonte":{"documento":"bncc-2018","arquivo":"BNCC_Ensino Fundamental.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comps. de Ciências da nature"}},{"id":"ef-area-ciencias-da-natureza-ce-06","documento":"bncc-2018","tipo":"especifica_de_area","area":"ef-area-ciencias-da-natureza","numero":6,"texto":"Utilizar diferentes linguagens e tecnologias digitais de informação e comunicação para se comunicar, acessar e disseminar informações, produzir conhecimentos e resolver problemas das Ciências da Natureza de forma crítica, significativa, reflexiva e ética.","fonte":{"documento":"bncc-2018","arquivo":"BNCC_Ensino Fundamental.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comps. de Ciências da nature"}},{"id":"ef-area-ciencias-da-natureza-ce-07","documento":"bncc-2018","tipo":"especifica_de_area","area":"ef-area-ciencias-da-natureza","numero":7,"texto":"Conhecer, apreciar e cuidar de si, do seu corpo e bem-estar, compreendendo-se na diversidade humana, fazendo-se respeitar e respeitando o outro, recorrendo aos conhecimentos das Ciências da Natureza e às suas tecnologias.","fonte":{"documento":"bncc-2018","arquivo":"BNCC_Ensino Fundamental.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comps. de Ciências da nature"}},{"id":"ef-area-ciencias-da-natureza-ce-08","documento":"bncc-2018","tipo":"especifica_de_area","area":"ef-area-ciencias-da-natureza","numero":8,"texto":"Agir pessoal e coletivamente com respeito, autonomia, responsabilidade, flexibilidade, resiliência e determinação, recorrendo aos conhecimentos das Ciências da Natureza para tomar decisões frente a questões científico-tecnológicas e socioambientais e a respeito da saúde individual e coletiva, com base em princípios éticos, democráticos, sustentáveis e solidários.","fonte":{"documento":"bncc-2018","arquivo":"BNCC_Ensino Fundamental.xlsx","proveniencia":"exportada de downloadbncc.mec.gov.br em 23/06/2023","localizador":"aba Comps. de Ciências da nature"}}]}},{"key":"ef-comp-ef","name":"Educação Física","metadata":{"datasetCommit":"daabd7dd63ae0cac0aa520b6189e79f95c24f583","competencies":[{"id":"ef-area-linguagens-ce-01","documento":"bncc-2018","tipo":"especifica_de_area","area":"ef-area-linguagens","numero":1,"texto":"Compreender as linguagens como construção humana, histórica, social e cultural, de natureza dinâmica, reconhecendo-as e valorizando-as como formas de significação da re