INSERT INTO curriculum_subjects(curriculum_version,source_key,name,stage,source_metadata)
SELECT 'BNCC-2018',x.key,x.name,'Ensino Fundamental',x.metadata FROM ef_bncc_payload p CROSS JOIN LATERAL jsonb_to_recordset(p.payload->'subjects') x(key text,name text,metadata jsonb)
WHERE true
ON CONFLICT(curriculum_version,name,stage) DO UPDATE SET source_key=EXCLUDED.source_key,source_metadata=EXCLUDED.source_metadata;
INSERT INTO knowledge_objects(subject_id,source_key,name,grade_range,source_metadata)
SELECT cs.id,x.key,x.name,x.grade,x.metadata FROM ef_bncc_payload p CROSS JOIN LATERAL jsonb_to_recordset(p.payload->'objects') x(key text,subject text,name text,grade text,metadata jsonb) JOIN curriculum_subjects cs ON cs.source_key=x.subject AND cs.curriculum_version='BNCC-2018'
WHERE true
ON CONFLICT(subject_id,name,grade_range) DO UPDATE SET source_key=EXCLUDED.source_key,source_metadata=EXCLUDED.source_metadata;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,knowledge_object_id,source_metadata,dataset_version,validity_status)
SELECT 'BNCC-2018',x.code,'Ensino Fundamental',x.subject,x.grade,x.description,ko.id,x.metadata,x.version,x.status FROM ef_bncc_payload p CROSS JOIN LATERAL jsonb_to_recordset(p.payload->'skills') x(code text,subject text,grade text,description text,objects jsonb,metadata jsonb,version text,status text)
JOIN curriculum_subjects cs ON cs.name=x.subject AND cs.stage='Ensino Fundamental' AND cs.curriculum_version='BNCC-2018' JOIN knowledge_objects ko ON ko.subject_id=cs.id AND ko.source_key=x.objects->>0
WHERE true
ON CONFLICT(curriculum_version,code) DO UPDATE SET stage=EXCLUDED.stage,subject=EXCLUDED.subject,grade_range=EXCLUDED.grade_range,description=EXCLUDED.description,knowledge_object_id=EXCLUDED.knowledge_object_id,source_metadata=EXCLUDED.source_metadata,dataset_version=EXCLUDED.dataset_version,validity_status=EXCLUDED.validity_status;
WITH missing AS (
 SELECT sk.id skill_id,ko.id object_id,ord FROM ef_bncc_payload p CROSS JOIN LATERAL jsonb_to_recordset(p.payload->'skills') x(code text,subject text,objects jsonb)
 CROSS JOIN LATERAL jsonb_array_elements_text(x.objects) WITH ORDINALITY o(key,ord)
 JOIN curriculum_skills sk ON sk.code=x.code AND sk.curriculum_version='BNCC-2018'
 JOIN curriculum_subjects cs ON cs.name=x.subject AND cs.stage='Ensino Fundamental' AND cs.curriculum_version='BNCC-2018'
 JOIN knowledge_objects ko ON ko.subject_id=cs.id AND ko.source_key=o.key
 WHERE NOT EXISTS(SELECT 1 FROM skill_knowledge_objects r WHERE r.skill_id=sk.id AND r.knowledge_object_id=ko.id)
) INSERT INTO skill_knowledge_objects(skill_id,knowledge_object_id,position)
SELECT m.skill_id,m.object_id,COALESCE((SELECT max(r.position) FROM skill_knowledge_objects r WHERE r.skill_id=m.skill_id),0)+row_number() OVER(PARTITION BY m.skill_id ORDER BY m.ord)::integer FROM missing m WHERE true ON CONFLICT DO NOTHING;
-- Mantém o catálogo pedagógico existente e completa os vínculos dos componentes.
INSERT INTO curriculum_areas(curriculum_version,source_key,name,stage) VALUES('BNCC-2018','ef-area-er','Ensino Religioso','Ensino Fundamental') ON CONFLICT DO NOTHING;
WITH catalog(area_key,name) AS (VALUES ('ef-area-linguagens','Língua Portuguesa'),('ef-area-linguagens','Arte'),('ef-area-linguagens','Educação Física'),('ef-area-linguagens','Língua Inglesa'),('ef-area-mat','Matemática'),('ef-area-cnt','Ciências'),('ef-area-ch','História'),('ef-area-ch','Geografia'),('ef-area-er','Ensino Religioso'))
INSERT INTO pedagogical_disciplines(institution_id,area_id,name,stage,created_by)
SELECT i.id,a.id,c.name,'Ensino Fundamental',u.id FROM institutions i CROSS JOIN catalog c JOIN curriculum_areas a ON a.source_key=c.area_key AND a.curriculum_version='BNCC-2018' CROSS JOIN LATERAL (SELECT id FROM users ORDER BY created_at,id LIMIT 1) u WHERE true ON CONFLICT(institution_id,area_id,name) DO NOTHING;
INSERT INTO pedagogical_discipline_skills(discipline_id,skill_id,tagged_by,rationale)
SELECT d.id,s.id,d.created_by,'BNCC-2018 Ensino Fundamental: vínculo pelo componente curricular.' FROM pedagogical_disciplines d JOIN curriculum_skills s ON s.subject=d.name AND s.stage='Ensino Fundamental' AND s.curriculum_version='BNCC-2018' WHERE d.stage='Ensino Fundamental' ON CONFLICT DO NOTHING;
DROP TABLE ef_bncc_payload;
